#!/usr/bin/env python3
"""
Round 191o (culprits-tiles-more), 8 October 2026.

- tipping/: the tipping points layer (Global Tipping Points Report 2025,
  CC BY-SA 4.0), built once from the report: tipping_points.places.geojson,
  tipping_points.boxes.json and the report's figures and maps in tipping/img/.
- bii_nhm.py: opens zips inside zips to find the GeoTIFF (the museum's zip
  holds another zip and a manifest).

Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/bii_nhm.py': '', 'tipping/tipping_points.places.geojson': '', 'tipping/tipping_points.boxes.json': '', 'tipping/img/fig_2_2_1_map.jpg': '', 'tipping/img/fig_2_4_1_register.jpg': '', 'tipping/img/map_africa.jpg': '', 'tipping/img/map_asia.jpg': '', 'tipping/img/map_australasia.jpg': '', 'tipping/img/map_europe.jpg': '', 'tipping/img/map_islands.jpg': '', 'tipping/img/map_north_america.jpg': '', 'tipping/img/map_south_america.jpg': '', 'tipping/img/table_2_4_1.jpg': '', 'tipping/img/table_2_4_3.jpg': '', 'tipping/img/table_2_4_4a.jpg': '', 'tipping/img/table_2_4_4b.jpg': ''}

def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round191o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round191o_tiles: wrote {path}")
    if not changed:
        print("round191o_tiles: already applied")


if __name__ == "__main__":
    main()
